const positionSandbox={mode:'cone',enemies:[],player:{x:90,y:250},angle:-12,range:250,spread:48,lineWidth:24,selected:'player',tool:'move',last:'',eliminated:new Set(),busy:false};
function randomizeSandbox(){const p=positionSandbox;p.enemies=Array.from({length:1+Math.floor(Math.random()*15)},(_,i)=>({id:i+1,x:130+Math.random()*400,y:35+Math.random()*315}));p.eliminated.clear();p.last='New group. Try moving yourself or rotating the attack.'}
randomizeSandbox();
function posClamp(v,a,b){return Math.min(b,Math.max(a,v))}
function posAngle(a){return (a*Math.PI)/180}
function posHits(){const p=positionSandbox, a=posAngle(p.angle),ux=Math.cos(a),uy=Math.sin(a),hit=[];for(const e of p.enemies){const dx=e.x-p.player.x,dy=e.y-p.player.y,along=dx*ux+dy*uy,cross=Math.abs(-dx*uy+dy*ux);if(along>=0&&along<=p.range&&(p.mode==='line'?cross<=p.lineWidth/2+9:cross<=Math.tan(posAngle(p.spread/2))*along+9))hit.push(e.id)}return hit}
function posPaint(){const el=$('position-arena');if(!el)return;const p=positionSandbox,a=posAngle(p.angle),ux=Math.cos(a),uy=Math.sin(a),nx=-uy,ny=ux,ex=p.player.x+ux*p.range,ey=p.player.y+uy*p.range;let shape;if(p.mode==='line'){const h=p.lineWidth/2;shape=`<polygon points="${p.player.x+nx*h},${p.player.y+ny*h} ${ex+nx*h},${ey+ny*h} ${ex-nx*h},${ey-ny*h} ${p.player.x-nx*h},${p.player.y-ny*h}" />`}else{const h=Math.tan(posAngle(p.spread/2))*p.range;shape=`<polygon points="${p.player.x},${p.player.y} ${ex+nx*h},${ey+ny*h} ${ex-nx*h},${ey-ny*h}" />`}const predicted=new Set(posHits());el.innerHTML=`<defs><pattern id="position-grid" width="40" height="40" patternUnits="userSpaceOnUse"><path d="M40 0H0V40" fill="none" stroke="#52667a" opacity=".2"/></pattern></defs><rect width="560" height="380" fill="#132133"/><rect width="560" height="380" fill="url(#position-grid)"/><g class="position-aim">${shape}</g>${p.enemies.map(e=>`<g data-enemy="${e.id}" class="position-enemy ${p.eliminated.has(e.id)?'is-eliminated':''} ${predicted.has(e.id)?'predicted-hit':''}"><circle cx="${e.x}" cy="${e.y}" r="12"/><text x="${e.x}" y="${e.y+4}" text-anchor="middle">${e.id}</text></g>`).join('')}<g class="position-player"><circle cx="${p.player.x}" cy="${p.player.y}" r="14"/><path d="M${p.player.x} ${p.player.y}L${p.player.x+ux*23} ${p.player.y+uy*23}"/></g><circle class="position-aim-knob" cx="${p.player.x+ux*70}" cy="${p.player.y+uy*70}" r="9"/>`;const status=$('position-status');if(status)status.textContent=`${predicted.size} of ${p.enemies.length} targets inside your ${p.mode==='line'?'line':'cone'} · ${p.last||'Drag yourself, drag the aiming handle, or change the targets.'}`}
function positionStudio(){const p=positionSandbox;return `<h2>Positioning Lab</h2><p class="muted">Move, aim, and explore your own ideas. Positions and ranges are illustrative rather than exact in-game hitboxes.</p><div class="position-layout"><section class="card position-stage"><svg id="position-arena" class="position-arena" viewBox="0 0 560 380" aria-label="Interactive attack planning field. Drag your blue character or the aiming handle; place, move or remove enemies."></svg><p id="position-status" class="hint" aria-live="polite"></p><div class="button-row"><button class="primary" data-act="pos-fire" id="position-attack">Attack</button><button data-act="pos-random">Randomize targets</button><button data-act="pos-reset">Restore eliminated</button></div></section><section class="card position-tools"><h3>Build your scenario</h3><label>On-field action<select id="pos-tool"><option value="move" ${p.tool==='move'?'selected':''}>Move character or enemies</option><option value="add" ${p.tool==='add'?'selected':''}>Place an enemy</option><option value="delete" ${p.tool==='delete'?'selected':''}>Remove an enemy</option></select></label><p class="hint">Click anywhere on the field to set your position when Move is selected. Drag a red target to reposition it, or drag the blue aiming handle to rotate.</p><label>Target count <input id="pos-count" type="number" min="1" max="15" value="${p.enemies.length}"></label><label>Attack shape<select id="pos-shape"><option value="cone" ${p.mode==='cone'?'selected':''}>Cone</option><option value="line" ${p.mode==='line'?'selected':''}>Line</option></select></label><label>Direction <output id="pos-angle-value">${p.angle}°</output><input id="pos-angle" type="range" min="-180" max="180" value="${p.angle}"></label><label>Reach <output id="pos-range-value">${p.range}</output><input id="pos-range" type="range" min="70" max="420" value="${p.range}"></label><label>${p.mode==='cone'?'Cone spread':'Line width'} <output id="pos-width-value">${p.mode==='cone'?p.spread+'°':p.lineWidth}</output><input id="pos-width" type="range" min="${p.mode==='cone'?10:10}" max="${p.mode==='cone'?120:90}" value="${p.mode==='cone'?p.spread:p.lineWidth}"></label><p class="hint">Aiming coverage considers enemy size. Attacking temporarily eliminates the targets your shape intersects, so you can plan what remains.</p></section></div>`}
function referencePage(){const key=state.arcana,ref=window.MIDIR_ROTATION_REFERENCE[key]||{name:key,summary:'Details being researched.',skills:[]};const pages=[`<button class="rotation-shortcut" data-act="hub:craft"><strong>Rotation Crafter</strong><span>Build hotbars, customize cooldowns and delays, and rehearse the current Arcana with its own character and target visuals.</span></button>`];if(key==='as')pages.push(`<button class="rotation-shortcut" data-act="hub:position"><strong>Positioning Lab</strong><span>Build enemy arrangements, adjust firing angle, and see which targets are reached.</span></button>`);if(key==='sg')pages.push(`<button class="rotation-shortcut" data-act="hub:oath"><strong>Oath Workshop</strong><span>Practice the defensive snapshot cascade, emergency re-Oath, and Golden Magic Wool timing.</span></button>`);if(key==='dd')pages.push(`<button class="rotation-shortcut" data-act="hub:dd-drill"><strong>Automaticity Training</strong><span>Thunder rhythm, recurring effects, self-assessment and attention rehearsal.</span></button>`);if(key==='hs')pages.push(`<button class="rotation-shortcut" data-act="hub:music-lie"><strong>Rate isn't a Lie</strong><span>Recreate the music buff calculator and rehearse Bard/Harmonic Saint performance buffs on screen.</span></button>`);if(key==='mp')pages.push(`<button class="rotation-shortcut" data-act="hub:erg"><strong>Erg Break Simulator</strong><span>Tap the divine mineral, advance B → A → S, and build a weapon collection.</span></button>`);if(key==='fa')pages.push(`<button class="rotation-shortcut" data-act="hub:herbs"><strong>Herb Collection</strong><span>Gather randomized herbs and add them to your Storage Chest.</span></button>`);if(key==='ev')pages.push(`<button class="rotation-shortcut" data-act="hub:reforge"><strong>Reforge Simulator</strong><span>Still looking for that 7/5 Cooldown hat?</span></button>`);return `<h2>${esc(ref.name)} · Rotation Lab</h2><p class="muted">${esc(ref.summary)}</p><h3>Available pages</h3><div class="rotation-shortcuts">${pages.join('')}</div><section class="card"><h2>Skill Knowledge</h2><p class="hint">Learn how skills contribute to resource cycles, movement, timing and damage windows. Skills and equipment interactions are described together.</p><div class="rotation-skill-grid">${ref.skills.map(([name,role,detail,evidence])=>{const fromData=window.MIDIR_DATA?.arcana?.[key]?.skills?.find(s=>s.name===name);const icon=window.MIDIR_ROTATION_ICONS?.[name]||(fromData&&window.MIDIR_ICONS?.skills?.[fromData.id]);return `<article class="rotation-skill-card">${icon?`<img class="midir-skill-icon" alt="" src="${esc(icon)}">`:''}<div><h3>${esc(name)}</h3><small class="gold">${esc(role)}</small><p>${esc(detail)}</p></div></article>`}).join('')}</div></section>`}
function rotationHub(){if(rotationView==='reference')return referencePage();const back=`<div class="rotation-back"><button data-act="hub:home">← Skill Knowledge & available pages</button></div>`;if(rotationView==='position'&&state.arcana==='as')return back+positionStudio();if(rotationView==='craft')return back+craftView();if(rotationView==='music-lie'&&state.arcana==='hs')return back+musicBuffLabView();if(rotationView==='reforge'&&state.arcana==='ev')return back+window.MIDIR_REFORGE.view();if(rotationView==='erg'&&state.arcana==='mp')return back+window.MIDIR_ERG.view();if(rotationView==='herbs'&&state.arcana==='fa')return back+window.MIDIR_HERBS.view();if(rotationView==='oath'&&state.arcana==='sg')return back+`<h2>Sacred Guardian · Oath Workshop</h2><p class="muted">Practice defensive snapshots, preparation, and recovery without a mandatory perfect rotation.</p><section class="card">${sgWorkshop()}</section>`;if(rotationView==='dd-drill'&&state.arcana==='dd')return back+dd();if(rotationView==='drill')return back+rotationOriginal();return back+rotationOriginal()}
