function bindPositionEvents(){const svg=$('position-arena');if(!svg)return;const p=positionSandbox;for(const [id,key] of [['pos-shape','mode'],['pos-tool','tool']])$(id)?.addEventListener('change',e=>{p[key]=e.target.value;render()});$('pos-count')?.addEventListener('change',e=>{const num=posClamp(Math.round(Number(e.target.value)||1),1,15);while(p.enemies.length<num)p.enemies.push({id:1+Math.max(0,...p.enemies.map(x=>x.id)),x:140+Math.random()*380,y:30+Math.random()*310});p.enemies=p.enemies.slice(0,num);p.eliminated.clear();render()});for(const [id,key] of [['pos-angle','angle'],['pos-range','range'],['pos-width',p.mode==='cone'?'spread':'lineWidth']])$(id)?.addEventListener('input',e=>{p[key]=Number(e.target.value);const out=$(id+'-value');if(out)out.textContent=p[key]+(key==='angle'||key==='spread'?'°':'');p.eliminated.clear();posPaint()});function coords(ev){const pt=svg.createSVGPoint();pt.x=ev.clientX;pt.y=ev.clientY;const m=svg.getScreenCTM();return m?pt.matrixTransform(m.inverse()):{x:0,y:0}}function update(ev){const c=coords(ev);if(dragPosition==='player'){p.player.x=posClamp(c.x,12,548);p.player.y=posClamp(c.y,12,368)}else if(dragPosition==='aim'){p.angle=Math.round(Math.atan2(c.y-p.player.y,c.x-p.player.x)*180/Math.PI);if($('pos-angle'))$('pos-angle').value=p.angle;if($('pos-angle-value'))$('pos-angle-value').textContent=p.angle+'°'}else if(typeof dragPosition==='number'){const en=p.enemies.find(e=>e.id===dragPosition);if(en){en.x=posClamp(c.x,12,548);en.y=posClamp(c.y,12,368)}}p.eliminated.clear();posPaint()}
svg.addEventListener('pointerdown',ev=>{const node=ev.target.closest('[data-enemy]');const c=coords(ev);if(p.tool==='add'){if(p.enemies.length<15)p.enemies.push({id:1+Math.max(0,...p.enemies.map(x=>x.id)),x:posClamp(c.x,12,548),y:posClamp(c.y,12,368)});p.last=p.enemies.length>=15?'Maximum 15 targets':'Target placed';p.eliminated.clear();posPaint();return}if(p.tool==='delete'){if(node&&p.enemies.length>1)p.enemies=p.enemies.filter(e=>e.id!==Number(node.dataset.enemy));p.last='Target removed';p.eliminated.clear();posPaint();return}dragPosition=ev.target.closest('.position-aim-knob')?'aim':ev.target.closest('.position-player')?'player':node?Number(node.dataset.enemy):'player';svg.setPointerCapture(ev.pointerId);update(ev)});svg.addEventListener('pointermove',ev=>{if(dragPosition!==null)update(ev)});const end=()=>{dragPosition=null};svg.addEventListener('pointerup',end);svg.addEventListener('pointercancel',end)}
